CREATE TABLE IF NOT EXISTS social_clients(id TEXT PRIMARY KEY,name TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_connections(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES social_clients(id),platform TEXT NOT NULL CHECK(platform IN ('facebook','instagram','threads')),account_id TEXT NOT NULL,page_id TEXT,display_name TEXT NOT NULL,encrypted_access_token TEXT NOT NULL,expires_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,UNIQUE(client_id,platform),UNIQUE(platform,account_id));
CREATE TABLE IF NOT EXISTS client_oauth_states(state TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES social_clients(id),platform TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_pending_connections(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES social_clients(id),platform TEXT NOT NULL,account_id TEXT NOT NULL,page_id TEXT,display_name TEXT NOT NULL,encrypted_access_token TEXT NOT NULL,expires_at INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_media(client_id TEXT NOT NULL REFERENCES social_clients(id),asset_id TEXT NOT NULL REFERENCES instagram_media_assets(id),PRIMARY KEY(client_id,asset_id));
CREATE TABLE IF NOT EXISTS client_post_groups(id TEXT PRIMARY KEY,client_id TEXT NOT NULL REFERENCES social_clients(id),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS client_posts(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES client_post_groups(id),client_id TEXT NOT NULL REFERENCES social_clients(id),connection_id TEXT NOT NULL REFERENCES client_connections(id),connection_version INTEGER NOT NULL,account_id TEXT NOT NULL,platform TEXT NOT NULL,display_name TEXT NOT NULL,caption TEXT NOT NULL,asset_id TEXT,scheduled_at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',container_id TEXT,media_id TEXT,error_message TEXT,updated_at INTEGER NOT NULL,UNIQUE(group_id,connection_id));
CREATE INDEX IF NOT EXISTS client_posts_due ON client_posts(status,scheduled_at);
